import subprocess
def run_comp(seq):
    p = subprocess.Popen(['./executable', 'comp'], stdin=subprocess.PIPE, stdout=subprocess.PIPE)
    out, _ = p.communicate(f'>s1\n{seq}\n'.encode())
    return out.decode().strip().split('\t')

iupac = 'ACGTURYSWKMBDHVN'
for c in iupac:
    res = run_comp(c)
    print(f'{c:2s}: len={res[1]} A={res[2]} C={res[3]} G={res[4]} T={res[5]} #2={res[6]} #3={res[7]} #4={res[8]} CpG={res[9]} tv={res[10]} ts={res[11]} CpG-ts={res[12]}')
""}

