// Targets for seed 11, n=2, i=2..5:
// i=2: k=1
// i=3: k>=2
// i=4: k=0
// i=5: k=1

int check_prng_float_drand48(uint64_t seed) {
    srand48(seed);
    int k2 = (int)(drand48() * 3);
    int k3 = (int)(drand48() * 4);
    int k4 = (int)(drand48() * 5);
    int k5 = (int)(drand48() * 6);
    return (k2 == 1 && k3 >= 2 && k4 == 0 && k5 == 1);
}

