    x = x * 6364136223846793005ULL + 1442695040888963407ULL;
    int k4 = (x >> 33) % 5;
    x = x * 6364136223846793005ULL + 1442695040888963407ULL;
    int k5 = (x >> 33) % 6;
    return (k2 == 1 && k3 >= 2 && k4 == 0 && k5 == 1);
}

int main() {
    printf("drand48 direct: %d\n", check_prng_float_drand48(11));
    return 0;
}
