{"command":"cat << 'EOF' > test_keys.c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int id;
    double key;
} Item;

int cmp(const void *a, const void *b) {
    double ka = ((Item*)a)->key;
    double kb = ((Item*)b)->key;
    if (ka < kb) return -1;
    if (ka > kb) return 1;
    return 0;
}

int cmp_rev(const void *a, const void *b) {
    return -cmp(a, b);
}

int main() {
    Item items[20];
    srand48(11);
    for (int i = 0; i < 20; i++) {
        items[i].id = i;
        items[i].key = drand48();
        printf("seq%d: %f\n", i, items[i].key);
    }

    qsort(items, 20, sizeof(Item), cmp);
    printf("\nSorted by key ascending:\n");
    for (int i = 0; i < 5; i++) {
        printf("seq%d: %f\n", items[i].id, items[i].key);
    }

    qsort(items, 20, sizeof(Item), cmp_rev);
    printf("\nSorted by key descending:\n");
    for (int i = 0; i < 5; i++) {
        printf("seq%d: %f\n", items[i].id, items[i].key);
    }
    return 0;
}
EOF
gcc test_keys.c -o test_keys
./test_keys
"}

