{"command":"cat << 'EOF' > test_prng_all.c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

// Knuth 64-bit LCG / SplitMix64 / PCG / Xorshift
uint64_t splitmix64(uint64_t *state) {
    uint64_t z = (*state += 0x9e3779b97f4a7c15ULL);
    z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
    z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
    return z ^ (z >> 31);
}

// Heng Li's krand / k48 PRNG:
// krand_t: uint64_t x[2];
// x[0] = seed, x[1] = seed ^ 0xda3e39cb9fb1a2d8ULL;
// static inline uint64_t kr_rand(krand_t *r)
// {
//     uint64_t x = r->x[0];
//     uint64_t const y = r->x[1];
//     r->x[0] = y;
//     x ^= x << 23;
//     r->x[1] = x ^ y ^ (x >> 17) ^ (y >> 26);
//     return r->x[1] + y;
// }

typedef struct {
    uint64_t x[2];
} krand_t;

void kr_srand(krand_t *r, uint64_t seed) {
    r->x[0] = seed;
    r->x[1] = seed ^ 0xda3e39cb9fb1a2d8ULL;
}

uint64_t kr_rand(krand_t *r) {
    uint64_t x = r->x[0];
    uint64_t const y = r->x[1];
    r->x[0] = y;
    x ^= x << 23;
    r->x[1] = x ^ y ^ (x >> 17) ^ (y >> 26);
    return r->x[1] + y;
}

double kr_drand(krand_t *r) {
    return (kr_rand(r) >> 11) * (1.0 / (1ULL << 53));
}

int main() {
    krand_t r;
    kr_srand(&r, 11);
    printf("kr_drand outputs:\n");
    for (int i = 0; i < 20; i++) {
        printf("seq%d: %f\n", i, kr_drand(&r));
    }
    return 0;
}
EOF
gcc test_prng_all.c -o test_prng_all
./test_prng_all
"}

