#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    uint64_t x[2];
} krand_t;

void kr_srand(krand_t *r, uint64_t seed) {
    r->x[0] = seed;
    r->x[1] = seed ^ 0xda3e39cb9fb1a2d8ULL;
}

uint64_t kr_rand(krand_t *r) {
    uint64_t x = r->x[0];
    uint64_t const y = r->x[1];
    r->x[0] = y;
    x ^= x << 23;
    r->x[1] = x ^ y ^ (x >> 17) ^ (y >> 26);
    return r->x[1] + y;
}

double kr_drand(krand_t *r) {
    return (kr_rand(r) >> 11) * (1.0 / (1ULL << 53));
}

int main() {
    // Option A: k = kr_rand(r) % (i + 1)
    {
        krand_t r;
        kr_srand(&r, 11);
        int N = 5;
        int res[5];
        for (int i = 0; i < N; i++) res[i] = i;
        for (int i = N; i < 20; i++) {
            uint64_t k = kr_rand(&r) % (i + 1);
            if (k < N) res[k] = i;
