// Target output for N=5, items=20, seed=11: res = {17, 11, 10, 14, 8}

// Test xorshift64star, splitmix64, pcg32, drand48, xoroshiro128+
uint64_t xorshift64s(uint64_t *state) {
    uint64_t x = *state;
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    *state = x;
    return x * 0x2545F4914F6CDD1DULL;
}

