#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

// Heng Li's krand.h
typedef struct {
    uint64_t x[2];
} krand_t;

static inline uint64_t kr_rand(krand_t *r) {
    uint64_t x = r->x[0];
    uint64_t const y = r->x[1];
    r->x[0] = y;
    x ^= x << 23;
    r->x[1] = x ^ y ^ (x >> 17) ^ (y >> 26);
    return r->x[1] + y;
}

static inline double kr_drand(krand_t *r) {
    return (kr_rand(r) >> 11) * (1.0 / (1ULL << 53));
}

typedef struct {
    int id;
    double key;
} HeapNode;

void heapify_down(HeapNode *heap, int size, int i) {
    int min_idx = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;
    if (left < size && heap[left].key < heap[min_idx].key) min_idx = left;
    if (right < size && heap[right].key < heap[min_idx].key) min_idx = right;
    if (min_idx != i) {
        HeapNode tmp = heap[i];
        heap[i] = heap[min_idx];
        heap[min_idx] = tmp;
        heapify_down(heap, size, min_idx);
    }
}

void heapify_up(HeapNode *heap, int i) {
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap[i].key < heap[parent].key) {
            HeapNode tmp = heap[i];
            heap[i] = heap[parent];
            heap[parent] = tmp;
            i = parent;
        } else break;
    }
}

