    int heap_size = 0;

    for (int i = 0; i < 20; i++) {
        double key = kr_drand(&r);
        if (heap_size < 5) {
            heap[heap_size].id = i;
            heap[heap_size].key = key;
            heap_size++;
            heapify_up(heap, heap_size - 1);
        } else if (key > heap[0].key) {
            heap[0].id = i;
            heap[0].key = key;
            heapify_down(heap, 5, 0);
        }
