#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

// Search PRNG formulas:
// For seed 11:
// seq17 and seq27 are < 0.01. seq0..seq16, seq18..seq26, seq28..seq99 are >= 0.01.

int check_seqs(double *vals) {
    if (vals[17] >= 0.01 || vals[27] >= 0.01) return 0;
    for (int i = 0; i < 100; i++) {
        if (i != 17 && i != 27 && vals[i] < 0.01) return 0;
    }
    return 1;
}

int main() {
    // 1. Heng Li's krand.h (xorshift128+)
    // x[0] = seed, x[1] = seed ^ CONST or CONST ^ seed
    uint64_t consts[] = {
        0xda3e39cb9fb1a2d8ULL,
        0x362ef2a912803c40ULL,
        0x9e3779b97f4a7c15ULL,
        0
    };

    for (int c = 0; c < 4; c++) {
        uint64_t x0 = 11;
        uint64_t x1 = 11 ^ consts[c];

        // try different shift constants
        // standard xorshift128+: x^=(x<<23), r[1]=x^y^(x>>17)^(y>>26)
        // or x^=(x<<a), r[1]=x^y^(x>>b)^(y>>c)
        double vals[100];
        uint64_t s0 = x0, s1 = x1;
        for (int i = 0; i < 100; i++) {
            uint64_t x = s0;
            uint64_t const y = s1;
            s0 = y;
            x ^= x << 23;
            s1 = x ^ y ^ (x >> 17) ^ (y >> 26);
            uint64_t res = s1 + y;
            vals[i] = (res >> 11) * (1.0 / (1ULL << 53));
        }
        if (check_seqs(vals)) printf("Match xorshift128+ c=%d!\n", c);
    }

    return 0;
}
EOF
gcc search_prng_all.c -o search_prng_all
./search_prng_all
"}

