    if (c05 != 4 || S[39] >= 0.05 || S[58] >= 0.05) return 0;

    // f=0.10
    int c10 = 0;
    for (int i = 0; i < 100; i++) if (S[i] < 0.10) c10++;
    if (c10 != 10) return 0;

    return 1;
}

