        krand_t r;
        r.x[0] = 11 + seed_variant;
        r.x[1] = (11 + seed_variant) ^ 0xda3e39cb9fb1a2d8ULL;

        double S[100];
        for (int i = 0; i < 100; i++) {
            uint64_t x = r.x[0];
            uint64_t const y = r.x[1];
