            r.x[1] = x ^ y ^ (x >> 17) ^ (y >> 26);
            uint64_t res = r.x[1] + y;
            S[i] = (res >> 11) * (1.0 / (1ULL << 53));
        }
        if (check_S(S)) {
            printf("MATCH seed_variant=%lu!\n", seed_variant);
        }
    }
    return 0;
}
