# We want PRNG(seed=11) to yield d < 0.01 at indices 17 and 27, and nowhere else in 0..99.

def check(gen):
    vals = [gen() for _ in range(100)]
    hits = [i for i, v in enumerate(vals) if v < 0.01]
    if hits == [17, 27]:
        return True, vals
    return False, hits

# Try 1: LCG with various parameters
for mult in [0x5DEECE66D, 6364136223846793005, 2862933555777941757, 1103515245, 1664525, 69069]:
    for add in [0xB, 1, 1013904223, 12345]:
        for mod in [1<<48, 1<<64, 1<<32]:
            for shift_type in [0, 1, 2]:
                state = 11
                def make_gen(m=mult, a=add, md=mod, st=shift_type):
                    s = 11
                    if md == 1<<48: s = (s << 16) | 0x330E
                    def next_val():
                        nonlocal s
                        s = (s * m + a) % md
                        if st == 0: return s / md
                        elif st == 1: return (s >> 16) / (md >> 16)
                        else: return (s >> 32) / (md >> 32)
                    return next_val
                ok, res = check(make_gen())
                if ok:
                    print(f"MATCH LCG mult={m} add={a} mod={md} st={shift_type}")

print("Search complete.")
