	char *fake_qual = 0, *mask_fn = 0;

	while ((c = getopt(argc, argv, "q:X:n:l:Q:s:f:M:L:F:crRA12VUxSN")) >= 0) {
		if (c == 'q') q_min = atoi(optarg);
