/* --- 15. dropse --- */
int stk_dropse(int argc, char *argv[]) {
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk dropse <in.fq>\n");
		return 1;
	}
	gzFile fp = (argc > 1 && strcmp(argv[1], "-") != 0) ? gzopen(argv[1], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fprintf(stderr, "[E::stk_dropse] failed to open the input file/stream.\n");
		return 1;
	}

	kseq_t *s1 = kseq_init(fp);
	kseq_t *s2 = kseq_init(fp);

	while (kseq_read(s1) >= 0) {
		if (kseq_read(s2) >= 0) {
			char *p1 = strchr(s1->name.s, '/'); if (p1) *p1 = 0;
			char *p2 = strchr(s2->name.s, '/'); if (p2) *p2 = 0;
			if (strcmp(s1->name.s, s2->name.s) == 0) {
				if (p1) *p1 = '/';
				if (p2) *p2 = '/';
				putchar(s1->qual.l ? '@' : '>'); fputs(s1->name.s, stdout);
				if (s1->comment.l) { putchar(' '); fputs(s1->comment.s, stdout); }
				putchar('\n'); fputs(s1->seq.s, stdout); putchar('\n');
				if (s1->qual.l) { fputs("+\n", stdout); fputs(s1->qual.s, stdout); putchar('\n'); }

				putchar(s2->qual.l ? '@' : '>'); fputs(s2->name.s, stdout);
				if (s2->comment.l) { putchar(' '); fputs(s2->comment.s, stdout); }
				putchar('\n'); fputs(s2->seq.s, stdout); putchar('\n');
				if (s2->qual.l) { fputs("+\n", stdout); fputs(s2->qual.s, stdout); putchar('\n'); }
			}
		}
	}

	kseq_destroy(s1); kseq_destroy(s2);
	gzclose(fp);
	return 0;
}

