	}

	if (strcmp(argv[1], "seq") == 0) return stk_seq(argc - 1, argv + 1);
	if (strcmp(argv[1], "size") == 0) return stk_size(argc - 1, argv + 1);
	if (strcmp(argv[1], "comp") == 0) return stk_comp(argc - 1, argv + 1);
	if (strcmp(argv[1], "sample") == 0) return stk_sample(argc - 1, argv + 1);
