/* --- 20. listhet --- */
int stk_listhet(int argc, char *argv[]) {
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk listhet <in.fa>\n");
		return 1;
	}
	gzFile fp = (argc > 1 && strcmp(argv[1], "-") != 0) ? gzopen(argv[1], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fprintf(stderr, "[E::stk_listhet] failed to open the input file/stream.\n");
		return 1;
	}

	kseq_t *seq = kseq_init(fp);
	init_tables();

	while (kseq_read(seq) >= 0) {
		for (size_t i = 0; i < seq->seq.l; ++i) {
			unsigned char b = seq_nt16_table[(unsigned char)seq->seq.s[i]];
			if (b != 15) {
				int pop = 0;
				for (int k = 0; k < 4; ++k) if ((b >> k) & 1) pop++;
				if (pop >= 2) {
					printf("%s\t%" PRId64 "\t%c\n", seq->name.s, (int64_t)i + 1, seq->seq.s[i]);
				}
			}
		}
	}

	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 21. hpc --- */
int stk_hpc(int argc, char *argv[]) {
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk hpc <in.fq>\n");
		return 1;
	}
	gzFile fp = (argc > 1 && strcmp(argv[1], "-") != 0) ? gzopen(argv[1], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fprintf(stderr, "[E::stk_hpc] failed to open the input file/stream.\n");
		return 1;
	}

	kseq_t *seq = kseq_init(fp);

	while (kseq_read(seq) >= 0) {
		printf(">%s\n", seq->name.s);
		char last = 0;
		for (size_t i = 0; i < seq->seq.l; ++i) {
			if (toupper(seq->seq.s[i]) != toupper(last)) {
				putchar(seq->seq.s[i]);
				last = seq->seq.s[i];
			}
		}
		putchar('\n');
	}

	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 22. telo --- */
int stk_telo(int argc, char *argv[]) {
	int c, penalty = 1, max_drop = 2000, min_score = 300, print_scoring = 0;
	char *motif = "CCCTAA";
	while ((c = getopt(argc, argv, "m:p:d:s:P")) >= 0) {
		if (c == 'm') motif = optarg;
		else if (c == 'p') penalty = atoi(optarg);
		else if (c == 'd') max_drop = atoi(optarg);
		else if (c == 's') min_score = atoi(optarg);
		else if (c == 'P') print_scoring = 1;
	}
	if (optind == argc && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk telo [options] <in.fq>\n");
		fprintf(stderr, "Options:\n");
		fprintf(stderr, "  -m STR     motif [CCCTAA]\n");
		fprintf(stderr, "  -p INT     penalty [1]\n");
		fprintf(stderr, "  -d INT     max drop [2000]\n");
		fprintf(stderr, "  -s INT     min score [300]\n");
		fprintf(stderr, "  -P         print scoring\n");
		return 1;
	}

	gzFile fp = (optind < argc && strcmp(argv[optind], "-") != 0) ? gzopen(argv[optind], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) return 1;

	kseq_t *seq = kseq_init(fp);
	size_t m_len = strlen(motif);

	while (kseq_read(seq) >= 0) {
		int score = 0;
		for (size_t i = 0; i < seq->seq.l; ++i) {
			if (toupper(seq->seq.s[i]) == toupper(motif[i % m_len])) {
				score++;
			} else {
				score -= penalty;
				if (score < 0) score = 0;
			}
			if (print_scoring) {
				printf("P\t%s\t%" PRId64 "\t%d\t%d\n", seq->name.s, (int64_t)i, score, score);
			}
		}
		fprintf(stderr, "0\t%" PRId64 "\n", (int64_t)seq->seq.l);
	}

	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

