/* --- 15. dropse --- */
int stk_dropse(int argc, char *argv[]) {
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk dropse <in.fq>\n");
		return 1;
	}
	gzFile fp = (argc > 1 && strcmp(argv[1], "-") != 0) ? gzopen(argv[1], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fprintf(stderr, "[E::stk_dropse] failed to open the input file/stream.\n");
		return 1;
	}

	kseq_t *s1 = kseq_init(fp);
	kseq_t *s2 = kseq_init(fp);

	while (kseq_read(s1) >= 0) {
		if (kseq_read(s2) >= 0) {
			char *p1 = strchr(s1->name.s, '/'); if (p1) *p1 = 0;
			char *p2 = strchr(s2->name.s, '/'); if (p2) *p2 = 0;
			if (strcmp(s1->name.s, s2->name.s) == 0) {
				if (p1) *p1 = '/';
				if (p2) *p2 = '/';
				putchar(s1->qual.l ? '@' : '>'); fputs(s1->name.s, stdout);
				if (s1->comment.l) { putchar(' '); fputs(s1->comment.s, stdout); }
				putchar('\n'); fputs(s1->seq.s, stdout); putchar('\n');
				if (s1->qual.l) { fputs("+\n", stdout); fputs(s1->qual.s, stdout); putchar('\n'); }

				putchar(s2->qual.l ? '@' : '>'); fputs(s2->name.s, stdout);
				if (s2->comment.l) { putchar(' '); fputs(s2->comment.s, stdout); }
				putchar('\n'); fputs(s2->seq.s, stdout); putchar('\n');
				if (s2->qual.l) { fputs("+\n", stdout); fputs(s2->qual.s, stdout); putchar('\n'); }
			}
		}
	}

	kseq_destroy(s1); kseq_destroy(s2);
	gzclose(fp);
	return 0;
}

/* --- 16. rename --- */
int stk_rename(int argc, char *argv[]) {
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk rename <in.fq> [prefix]\n");
		return 1;
	}
	gzFile fp = (argc > 1 && strcmp(argv[1], "-") != 0) ? gzopen(argv[1], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fprintf(stderr, "[E::stk_rename] failed to open the input file/stream.\n");
		return 1;
	}

	char *prefix = argc > 2 ? argv[2] : "";
	kseq_t *seq = kseq_init(fp);
	int64_t count = 0;

	while (kseq_read(seq) >= 0) {
		count++;
		putchar(seq->qual.l ? '@' : '>');
		printf("%s%" PRId64, prefix, count);
		if (seq->comment.l) { putchar(' '); fputs(seq->comment.s, stdout); }
		putchar('\n');
		fputs(seq->seq.s, stdout); putchar('\n');
		if (seq->qual.l) {
			fputs("+\n", stdout); fputs(seq->qual.s, stdout); putchar('\n');
		}
	}

	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 17. randbase --- */
int stk_randbase(int argc, char *argv[]) {
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk randbase <in.fa>\n");
		return 1;
	}
	gzFile fp = (argc > 1 && strcmp(argv[1], "-") != 0) ? gzopen(argv[1], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fprintf(stderr, "[E::stk_randbase] failed to open the input file/stream.\n");
		return 1;
	}

	kseq_t *seq = kseq_init(fp);
	init_tables();
	krand_t *kr = kr_srand(11);

	while (kseq_read(seq) >= 0) {
		printf(">%s\n", seq->name.s);
		for (size_t i = 0; i < seq->seq.l; ++i) {
			unsigned char b = seq_nt16_table[(unsigned char)seq->seq.s[i]];
			int bases[4], n_b = 0;
			for (int k = 0; k < 4; ++k) if ((b >> k) & 1) bases[n_b++] = k;
			if (n_b > 1) {
				int choice = (int)(kr_drand(kr) * n_b);
				char canonical[] = "ACGT";
				putchar(islower(seq->seq.s[i]) ? tolower(canonical[bases[choice]]) : canonical[bases[choice]]);
			} else {
				putchar(seq->seq.s[i]);
			}
		}
		putchar('\n');
	}

	free(kr);
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 18. cutN --- */
int stk_cutN(int argc, char *argv[]) {
	int c, min_N = 1000, penalty = 10, gaps_only = 0;
	while ((c = getopt(argc, argv, "n:p:g")) >= 0) {
		if (c == 'n') min_N = atoi(optarg);
		else if (c == 'p') penalty = atoi(optarg);
		else if (c == 'g') gaps_only = 1;
	}
	if (optind == argc && isatty(fileno(stdin))) {
		fprintf(stderr, "\nUsage:   seqtk cutN [options] <in.fa>\n\n");
		fprintf(stderr, "Options: -n INT    min size of N tract [1000]\n");
		fprintf(stderr, "         -p INT    penalty for a non-N [10]\n");
		fprintf(stderr, "         -g        print gaps only, no sequence\n\n");
		return 1;
	}

	gzFile fp = (optind < argc && strcmp(argv[optind], "-") != 0) ? gzopen(argv[optind], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) return 1;

	kseq_t *seq = kseq_init(fp);
	init_tables();

	while (kseq_read(seq) >= 0) {
		int64_t st = 0, n_cnt = 0;
		int in_gap = 0;
		int64_t gap_st = -1;

		for (size_t i = 0; i < seq->seq.l; ++i) {
			unsigned char b = seq_nt16_table[(unsigned char)seq->seq.s[i]];
			if (b == 15) {
				if (!in_gap) { gap_st = i; in_gap = 1; }
				n_cnt++;
			} else {
				if (in_gap && n_cnt >= min_N) {
					if (gaps_only) {
						printf("%s\t%" PRId64 "\t%" PRId64 "\n", seq->name.s, gap_st, (int64_t)i);
					} else {
						if (gap_st > st) {
							printf(">%s:%" PRId64 "-%" PRId64 "\n", seq->name.s, st + 1, gap_st);
							fwrite(seq->seq.s + st, 1, gap_st - st, stdout); putchar('\n');
						}
						st = i;
					}
				}
				in_gap = 0; n_cnt = 0;
			}
		}
		if (in_gap && n_cnt >= min_N && gaps_only) {
			printf("%s\t%" PRId64 "\t%" PRId64 "\n", seq->name.s, gap_st, (int64_t)seq->seq.l);
		} else if (!gaps_only && (int64_t)seq->seq.l > st) {
			if (st == 0) printf(">%s:%" PRId64 "-%" PRId64 "\n", seq->name.s, st + 1, (int64_t)seq->seq.l);
			else printf(">%s:%" PRId64 "-%" PRId64 "\n", seq->name.s, st + 1, (int64_t)seq->seq.l);
			fwrite(seq->seq.s + st, 1, seq->seq.l - st, stdout); putchar('\n');
		}
	}

	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 19. gap --- */
int stk_gap(int argc, char *argv[]) {
	int c, min_len = 50;
	while ((c = getopt(argc, argv, "l:")) >= 0) {
		if (c == 'l') min_len = atoi(optarg);
	}
	if (optind == argc && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk gap [-l 50] <in.fa>\n");
		return 1;
	}

	gzFile fp = (optind < argc && strcmp(argv[optind], "-") != 0) ? gzopen(argv[optind], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) return 1;

	kseq_t *seq = kseq_init(fp);
	init_tables();

	while (kseq_read(seq) >= 0) {
		int in_gap = 0;
		int64_t gap_st = -1, n_cnt = 0;
		for (size_t i = 0; i < seq->seq.l; ++i) {
			unsigned char b = seq_nt16_table[(unsigned char)seq->seq.s[i]];
			if (b == 15) {
				if (!in_gap) { gap_st = i; in_gap = 1; }
				n_cnt++;
			} else {
				if (in_gap && n_cnt >= min_len) {
					printf("%s\t%" PRId64 "\t%" PRId64 "\n", seq->name.s, gap_st, (int64_t)i);
				}
				in_gap = 0; n_cnt = 0;
			}
		}
		if (in_gap && n_cnt >= min_len) {
			printf("%s\t%" PRId64 "\t%" PRId64 "\n", seq->name.s, gap_st, (int64_t)seq->seq.l);
		}
