	if (strcmp(argv[1], "fqchk") == 0) return stk_fqchk(argc - 1, argv + 1);
	if (strcmp(argv[1], "mergepe") == 0) return stk_mergepe(argc - 1, argv + 1);
	if (strcmp(argv[1], "split") == 0) return stk_split(argc - 1, argv + 1);
	if (strcmp(argv[1], "trimfq") == 0) return stk_trimfq(argc - 1, argv + 1);
	if (strcmp(argv[1], "hety") == 0) return stk_hety(argc - 1, argv + 1);
	if (strcmp(argv[1], "gc") == 0) return stk_gc(argc - 1, argv + 1);
	if (strcmp(argv[1], "mutfa") == 0) return stk_mutfa(argc - 1, argv + 1);
	if (strcmp(argv[1], "mergefa") == 0) return stk_mergefa(argc - 1, argv + 1);
	if (strcmp(argv[1], "famask") == 0) return stk_famask(argc - 1, argv + 1);
	if (strcmp(argv[1], "dropse") == 0) return stk_dropse(argc - 1, argv + 1);
	if (strcmp(argv[1], "rename") == 0) return stk_rename(argc - 1, argv + 1);
	if (strcmp(argv[1], "randbase") == 0) return stk_randbase(argc - 1, argv + 1);
	if (strcmp(argv[1], "cutN") == 0) return stk_cutN(argc - 1, argv + 1);
	if (strcmp(argv[1], "gap") == 0) return stk_gap(argc - 1, argv + 1);
	if (strcmp(argv[1], "listhet") == 0) return stk_listhet(argc - 1, argv + 1);
	if (strcmp(argv[1], "hpc") == 0) return stk_hpc(argc - 1, argv + 1);
	if (strcmp(argv[1], "telo") == 0) return stk_telo(argc - 1, argv + 1);

	fprintf(stderr, "[main] unrecognized command '%s'. Abort!\n", argv[1]);
	return 1;
}
