    // Target output: ACGTGTGTTC
    char bases[6][2] = {{'A','G'}, {'C','T'}, {'C','G'}, {'A','T'}, {'G','T'}, {'A','C'}};

    // Test with kr_rand(kr)
    for (int every_base = 0; every_base < 2; every_base++) {
        for (int method = 0; method < 3; method++) {
            krand_t *kr = kr_srand(11);
            char res[11] = "ACGT";
            int het_i = 0;
            for (int i = 0; i < 10; i++) {
                if (!every_base && i < 4) continue;
                double d = 0;
                uint64_t r = 0;
                if (method == 0) r = kr_rand(kr);
                else if (method == 1) d = kr_drand(kr);

                if (i >= 4) {
                    int choice = 0;
                    if (method == 0) choice = r % 2;
                    else if (method == 1) choice = (int)(d * 2);
                    res[i] = bases[het_i++][choice];
                }
