static uint64_t simdrand_seed = 1;

void simsrand48(long seed) {
    simdrand_seed = (uint64_t)seed << 16 | 0x330E;
}

double simdrand48(void) {
    simdrand_seed = (simdrand_seed * 0x5DEECE66DULL + 0xBULL) & 0xFFFFFFFFFFFFULL;
    return (double)simdrand_seed / 281474976710656.0;
}

int main() {
    for (int init_type = 0; init_type < 4; init_type++) {
        for (int calls = 0; calls < 10; calls++) {
            if (init_type == 0) simsrand48(11);
            else if (init_type == 1) simdrand_seed = 11;
            else if (init_type == 2) simdrand_seed = 11 << 16;
            else simdrand_seed = 11 ^ 0x330E;

            for (int c = 0; c < calls; c++) simdrand48();

            int ok = 1;
            int expected[10] = {1, 0, 1, 0, 1, 1, 0, 0, 0, 0}; // s0, s2, s4, s5
            for (int i = 0; i < 10; i++) {
                double d = simdrand48();
                int kept = (d < 0.5);
                if (kept != expected[i]) ok = 0;
            }
            if (ok) {
                printf("MATCH simdrand init=%d calls=%d!\n", init_type, calls);
            }
        }
    }
    return 0;
}
EOF
