			if (is_match) {
				if (score <= 0) reg_st = i;
				score += match_score;
				last_en = i + 1;
				if (score > max_score) {
					max_score = score;
					max_st = reg_st;
					max_en = last_en;
				}
			} else {
				score -= mismatch_penalty;
				if (score <= 0) {
					if (max_en - max_st >= min_len) {
						printf("%s\\t%" PRId64 "\\t%" PRId64 "\\t%" PRId64 "\\n", seq->name.s, max_st + 1, max_en, max_en - max_st);
					}
					score = 0;
					max_score = 0;
				}
			}
		}
		if (max_score > 0 && max_en - max_st >= min_len) {
			printf("%s\\t%" PRId64 "\\t%" PRId64 "\\t%" PRId64 "\\n", seq->name.s, max_st + 1, max_en, max_en - max_st);
		}
	}

	kseq_destroy(seq);
	gzclose(fp);
	return 0;
