import sys

header = '''#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <math.h>
#include <ctype.h>
#include <getopt.h>
#include <stdint.h>
#include <inttypes.h>
#include <zlib.h>

