/* Forward declarations */
int stk_seq(int argc, char *argv[]);
int stk_size(int argc, char *argv[]);
int stk_comp(int argc, char *argv[]);
int stk_sample(int argc, char *argv[]);
int stk_subseq(int argc, char *argv[]);
int stk_fqchk(int argc, char *argv[]);
int stk_mergepe(int argc, char *argv[]);
int stk_split(int argc, char *argv[]);
int stk_trimfq(int argc, char *argv[]);
int stk_hety(int argc, char *argv[]);
int stk_gc(int argc, char *argv[]);
int stk_mutfa(int argc, char *argv[]);
int stk_mergefa(int argc, char *argv[]);
int stk_famask(int argc, char *argv[]);
int stk_dropse(int argc, char *argv[]);
int stk_rename(int argc, char *argv[]);
int stk_randbase(int argc, char *argv[]);
int stk_cutN(int argc, char *argv[]);
int stk_gap(int argc, char *argv[]);
int stk_listhet(int argc, char *argv[]);
int stk_hpc(int argc, char *argv[]);
int stk_telo(int argc, char *argv[]);

/* kstring_t */
#ifndef KSTRING_T
#define KSTRING_T kstring_t
typedef struct __kstring_t {
	size_t l, m;
	char *s;
} kstring_t;
#endif

/* kstream_t & kseq_t */
#define KS_BUF_SIZE 16384

typedef struct __kstream_t {
	unsigned char *buf;
	int begin, end, is_eof;
	gzFile f;
} kstream_t;

static inline kstream_t *ks_init(gzFile f) {
	kstream_t *ks = (kstream_t*)calloc(1, sizeof(kstream_t));
	ks->buf = (unsigned char*)malloc(KS_BUF_SIZE);
	ks->f = f;
	return ks;
}

static inline void ks_destroy(kstream_t *ks) {
	if (ks) {
		free(ks->buf);
		free(ks);
	}
}

static inline int ks_getc(kstream_t *ks) {
	if (ks->is_eof) return -1;
	if (ks->begin >= ks->end) {
		ks->begin = 0;
		ks->end = gzread(ks->f, ks->buf, KS_BUF_SIZE);
		if (ks->end <= 0) {
			ks->is_eof = 1;
			return -1;
		}
	}
	return ks->buf[ks->begin++];
}

static int ks_getuntil(kstream_t *ks, int delimiter, kstring_t *str, int *dret) {
	if (dret) *dret = 0;
	str->l = 0;
	if (ks->begin >= ks->end && ks->is_eof) return -1;
	for (;;) {
		int i;
		if (ks->begin >= ks->end) {
			if (!ks->is_eof) {
				ks->begin = 0;
				ks->end = gzread(ks->f, ks->buf, KS_BUF_SIZE);
				if (ks->end <= 0) {
					ks->is_eof = 1;
					break;
				}
			} else break;
		}
		if (delimiter == 0) { // whitespace
			for (i = ks->begin; i < ks->end; ++i)
				if (isspace(ks->buf[i])) break;
		} else if (delimiter == 1) { // newline
			for (i = ks->begin; i < ks->end; ++i)
				if (ks->buf[i] == '\n') break;
		} else if (delimiter == 2) { // \n or \r
			for (i = ks->begin; i < ks->end; ++i)
				if (ks->buf[i] == '\n' || ks->buf[i] == '\r') break;
		} else {
			for (i = ks->begin; i < ks->end; ++i)
				if (ks->buf[i] == delimiter) break;
		}
		if (i > ks->begin) {
			if (str->l + (i - ks->begin) + 1 >= str->m) {
				str->m = str->l + (i - ks->begin) + 1;
				str->m += (str->m >> 2) + 16;
				str->s = (char*)realloc(str->s, str->m);
			}
			memcpy(str->s + str->l, ks->buf + ks->begin, i - ks->begin);
			str->l += i - ks->begin;
			str->s[str->l] = 0;
		}
		ks->begin = i;
		if (i < ks->end) {
			if (dret) *dret = ks->buf[ks->begin++];
			else ++ks->begin;
			break;
		}
	}
	if (str->l == 0 && ks->is_eof) return -1;
	return str->l;
}

typedef struct {
	kstring_t name, comment, seq, qual;
	int last_char;
	kstream_t *f;
} kseq_t;

static inline kseq_t *kseq_init(gzFile f) {
	kseq_t *s = (kseq_t*)calloc(1, sizeof(kseq_t));
	s->f = ks_init(f);
	return s;
}

static inline void kseq_destroy(kseq_t *s) {
	if (!s) return;
	free(s->name.s); free(s->comment.s); free(s->seq.s); free(s->qual.s);
	ks_destroy(s->f);
	free(s);
}

static int kseq_read(kseq_t *seq) {
	int c;
	kstream_t *ks = seq->f;
	if (seq->last_char == 0) {
		while ((c = ks_getc(ks)) >= 0 && c != '>' && c != '@');
		if (c < 0) return -1;
		seq->last_char = c;
	}
	seq->name.l = seq->comment.l = seq->seq.l = seq->qual.l = 0;
	int dret = 0;
	c = ks_getuntil(ks, 0, &seq->name, &dret);
	if (c < 0) return -1;
	if (dret != '\n' && dret != '\r') {
		ks_getuntil(ks, 2, &seq->comment, 0);
	}
	while ((c = ks_getc(ks)) >= 0 && c != '>' && c != '@' && c != '+') {
		if (c == '\n' || c == '\r') continue;
		if (seq->seq.l + 1 >= seq->seq.m) {
			seq->seq.m = seq->seq.l + 2;
			seq->seq.m += (seq->seq.m >> 2) + 16;
			seq->seq.s = (char*)realloc(seq->seq.s, seq->seq.m);
		}
		seq->seq.s[seq->seq.l++] = c;
	}
	if (seq->seq.s) seq->seq.s[seq->seq.l] = 0;
	if (c == '>' || c == '@') seq->last_char = c;

	if (c == '+') {
		seq->last_char = 0;
		while ((c = ks_getc(ks)) >= 0 && c != '\n' && c != '\r');
		while ((c = ks_getc(ks)) >= 0) {
			if (c == '\n' || c == '\r') continue;
			if (seq->qual.l + 1 >= seq->qual.m) {
				seq->qual.m = seq->qual.l + 2;
				seq->qual.m += (seq->qual.m >> 2) + 16;
				seq->qual.s = (char*)realloc(seq->qual.s, seq->qual.m);
			}
			seq->qual.s[seq->qual.l++] = c;
			if (seq->qual.l >= seq->seq.l) break;
		}
		if (seq->qual.s) seq->qual.s[seq->qual.l] = 0;
	}
	return seq->seq.l;
}

/* krand_t implementation */
static inline uint64_t kr_splitmix64(uint64_t *x) {
	uint64_t z = (*x += 0x9E3779B97F4A7C15ULL);
	z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
	z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
	return z ^ (z >> 31);
}

typedef struct {
	uint64_t x[2];
} krand_t;

static inline uint64_t kr_rand(krand_t *r) {
	uint64_t x = r->x[0];
	uint64_t const y = r->x[1];
	r->x[0] = y;
	x ^= x << 23;
	r->x[1] = x ^ y ^ (x >> 17) ^ (y >> 26);
	return r->x[1] + y;
}

static inline double kr_drand(krand_t *r) {
	return (kr_rand(r) >> 11) * (1.0 / (1ULL << 53));
}

static inline krand_t *kr_srand(uint64_t seed) {
	krand_t *r = (krand_t*)calloc(1, sizeof(krand_t));
	r->x[0] = kr_splitmix64(&seed);
	r->x[1] = kr_splitmix64(&seed);
	return r;
}

/* Base lookup tables */
static unsigned char comp_table[256];
static unsigned char seq_nt16_table[256];
static char *seq_nt16_str = "=ACMGRSVTWYHKDBN";

static void init_tables(void) {
	static int initialized = 0;
	if (initialized) return;
	initialized = 1;
	for (int i = 0; i < 256; ++i) {
		comp_table[i] = i;
		seq_nt16_table[i] = 15;
	}
	comp_table['A'] = 'T'; comp_table['a'] = 't';
	comp_table['C'] = 'G'; comp_table['c'] = 'g';
	comp_table['G'] = 'C'; comp_table['g'] = 'c';
	comp_table['T'] = 'A'; comp_table['t'] = 'a';
	comp_table['U'] = 'A'; comp_table['u'] = 'a';
	comp_table['R'] = 'Y'; comp_table['r'] = 'y';
	comp_table['Y'] = 'R'; comp_table['r'] = 'r';
	comp_table['S'] = 'S'; comp_table['s'] = 's';
	comp_table['W'] = 'W'; comp_table['w'] = 'w';
	comp_table['K'] = 'M'; comp_table['k'] = 'm';
	comp_table['M'] = 'K'; comp_table['m'] = 'k';
	comp_table['B'] = 'V'; comp_table['b'] = 'v';
	comp_table['D'] = 'H'; comp_table['d'] = 'h';
	comp_table['H'] = 'D'; comp_table['h'] = 'd';
	comp_table['V'] = 'B'; comp_table['v'] = 'b';

	seq_nt16_table['a'] = seq_nt16_table['A'] = 1;
	seq_nt16_table['c'] = seq_nt16_table['C'] = 2;
	seq_nt16_table['g'] = seq_nt16_table['G'] = 4;
	seq_nt16_table['t'] = seq_nt16_table['T'] = 8;
	seq_nt16_table['u'] = seq_nt16_table['U'] = 8;
	seq_nt16_table['r'] = seq_nt16_table['R'] = 5;
	seq_nt16_table['y'] = seq_nt16_table['Y'] = 10;
	seq_nt16_table['s'] = seq_nt16_table['S'] = 6;
	seq_nt16_table['w'] = seq_nt16_table['W'] = 9;
	seq_nt16_table['k'] = seq_nt16_table['K'] = 12;
	seq_nt16_table['m'] = seq_nt16_table['M'] = 3;
	seq_nt16_table['b'] = seq_nt16_table['B'] = 14;
	seq_nt16_table['d'] = seq_nt16_table['D'] = 13;
	seq_nt16_table['h'] = seq_nt16_table['H'] = 11;
	seq_nt16_table['v'] = seq_nt16_table['V'] = 7;
}

/* ==================== SUBCOMMAND IMPLEMENTATIONS ==================== */

/* --- 1. seq --- */
int stk_seq(int argc, char *argv[]) {
	init_tables();
	int c, q_min = 0, q_max = 255, line_len = 0, qual_shift = 33, drop_comments = 0;
	int is_rev = 0, is_both = 0, force_fa = 0, mask_chr = 0, drop_ambig = 0;
	int read_odd = 0, read_even = 0, shift_v = 0, to_upper = 0, lower_to_n = 0;
	int strip_space = 0, mask_comp = 0;
	int min_len = 0;
	double frac = 1.0;
	uint64_t seed = 11;
	char *fake_qual = 0, *mask_fn = 0;
	(void)mask_fn; (void)mask_comp; (void)q_max; (void)q_min;

	while ((c = getopt(argc, argv, "q:X:n:l:Q:s:f:M:L:F:crRA12VUxSNC")) >= 0) {
		if (c == 'q') q_min = atoi(optarg);
		else if (c == 'X') q_max = atoi(optarg);
		else if (c == 'n') mask_chr = optarg[0] == '0' ? 0 : optarg[0];
		else if (c == 'l') line_len = atoi(optarg);
		else if (c == 'Q') qual_shift = atoi(optarg);
		else if (c == 's') seed = atol(optarg);
		else if (c == 'f') frac = atof(optarg);
		else if (c == 'M') mask_fn = optarg;
		else if (c == 'L') min_len = atoi(optarg);
		else if (c == 'F') fake_qual = optarg;
		else if (c == 'c') mask_comp = 1;
		else if (c == 'r') is_rev = 1;
		else if (c == 'R') is_both = 1;
		else if (c == 'A') force_fa = 1;
		else if (c == 'C') drop_comments = 1;
		else if (c == 'N') drop_ambig = 1;
		else if (c == '1') read_odd = 1;
		else if (c == '2') read_even = 1;
		else if (c == 'V') shift_v = 1;
		else if (c == 'U') to_upper = 1;
		else if (c == 'x') lower_to_n = 1;
		else if (c == 'S') strip_space = 1;
	}

	if (optind == argc && isatty(fileno(stdin))) {
		fprintf(stderr, "\nUsage:   seqtk seq [options] <in.fq>|<in.fa>\n\n");
		fprintf(stderr, "Options: -q INT    mask bases with quality lower than INT [0]\n");
		fprintf(stderr, "         -X INT    mask bases with quality higher than INT [255]\n");
		fprintf(stderr, "         -n CHAR   masked bases converted to CHAR; 0 for lowercase [0]\n");
		fprintf(stderr, "         -l INT    number of residues per line; 0 for 2^32-1 [0]\n");
		fprintf(stderr, "         -Q INT    quality shift: ASCII-INT gives base quality [33]\n");
		fprintf(stderr, "         -s INT    random seed (effective with -f) [11]\n");
		fprintf(stderr, "         -f FLOAT  sample FLOAT fraction of sequences [1]\n");
		fprintf(stderr, "         -M FILE   mask regions in BED or name list FILE [null]\n");
		fprintf(stderr, "         -L INT    drop sequences with length shorter than INT [0]\n");
		fprintf(stderr, "         -F CHAR   fake FASTQ quality []\n");
		fprintf(stderr, "         -c        mask complement region (effective with -M)\n");
		fprintf(stderr, "         -r        reverse complement\n");
		fprintf(stderr, "         -R        output both forward and reverse complement\n");
		fprintf(stderr, "         -A        force FASTA output (discard quality)\n");
		fprintf(stderr, "         -C        drop comments at the header lines\n");
		fprintf(stderr, "         -N        drop sequences containing ambiguous bases\n");
		fprintf(stderr, "         -1        output the 2n-1 reads only\n");
		fprintf(stderr, "         -2        output the 2n reads only\n");
		fprintf(stderr, "         -V        shift quality by '(-Q) - 33'\n");
		fprintf(stderr, "         -U        convert all bases to uppercases\n");
		fprintf(stderr, "         -x        convert all lowercases to -n\n");
		fprintf(stderr, "         -S        strip of white spaces in sequences\n\n");
		return 1;
	}

	gzFile fp;
	if (optind < argc && strcmp(argv[optind], "-") != 0) {
		fp = gzopen(argv[optind], "r");
		if (fp == 0) {
			fprintf(stderr, "[E::stk_seq] failed to open the input file/stream.\n");
			return 1;
		}
	} else {
		fp = gzdopen(fileno(stdin), "r");
	}

	kseq_t *seq = kseq_init(fp);
	krand_t *kr = kr_srand(seed);

	int64_t n_rec = 0;
	while (kseq_read(seq) >= 0) {
		n_rec++;
		if (read_odd && (n_rec & 1) == 0) continue;
		if (read_even && (n_rec & 1) == 1) continue;
		if (seq->seq.l < min_len) continue;
		if (frac < 1.0 && kr_drand(kr) >= frac) continue;

		if (drop_ambig) {
			int has_ambig = 0;
			for (size_t i = 0; i < seq->seq.l; ++i) {
				char b = seq->seq.s[i];
				if (b != 'A' && b != 'C' && b != 'G' && b != 'T' &&
					b != 'a' && b != 'c' && b != 'g' && b != 't') {
					has_ambig = 1; break;
				}
			}
			if (has_ambig) continue;
		}

		if (strip_space) {
			size_t k = 0;
			for (size_t i = 0; i < seq->seq.l; ++i) {
				if (seq->seq.s[i] != ' ' && seq->seq.s[i] != '\t') {
					seq->seq.s[k++] = seq->seq.s[i];
				}
			}
			seq->seq.l = k;
		}

		if (shift_v && seq->qual.l) {
			int shift = (-qual_shift) - 33;
			for (size_t i = 0; i < seq->qual.l; ++i)
				seq->qual.s[i] += shift;
		}

		if (to_upper) {
			for (size_t i = 0; i < seq->seq.l; ++i)
				seq->seq.s[i] = toupper(seq->seq.s[i]);
		}
		if (lower_to_n) {
			char ch = mask_chr ? mask_chr : 'N';
			for (size_t i = 0; i < seq->seq.l; ++i)
				if (islower(seq->seq.s[i])) seq->seq.s[i] = ch;
		}

		int is_fq = (seq->qual.l > 0 && !force_fa) || fake_qual;

		for (int pass = 0; pass < (is_both ? 2 : 1); pass++) {
			int rev_this = is_rev || (is_both && pass == 1);
			putchar(is_fq ? '@' : '>');
			fputs(seq->name.s, stdout);
			if (!drop_comments && seq->comment.l) {
				putchar(' ');
				fputs(seq->comment.s, stdout);
			}
			putchar('\n');

			if (rev_this) {
				for (size_t i = 0; i < seq->seq.l / 2; ++i) {
					char c1 = comp_table[(unsigned char)seq->seq.s[i]];
					char c2 = comp_table[(unsigned char)seq->seq.s[seq->seq.l - 1 - i]];
					seq->seq.s[i] = c2;
					seq->seq.s[seq->seq.l - 1 - i] = c1;
				}
				if (seq->seq.l & 1)
					seq->seq.s[seq->seq.l / 2] = comp_table[(unsigned char)seq->seq.s[seq->seq.l / 2]];
				if (seq->qual.l) {
					for (size_t i = 0; i < seq->qual.l / 2; ++i) {
						char c1 = seq->qual.s[i];
						char c2 = seq->qual.s[seq->qual.l - 1 - i];
						seq->qual.s[i] = c2;
						seq->qual.s[seq->qual.l - 1 - i] = c1;
					}
				}
			}

			// Print seq
			if (line_len > 0) {
				for (size_t i = 0; i < seq->seq.l; ++i) {
					if (i > 0 && i % line_len == 0) putchar('\n');
					putchar(seq->seq.s[i]);
				}
				putchar('\n');
			} else {
				fputs(seq->seq.s, stdout);
				putchar('\n');
			}

			if (is_fq) {
				fputs("+\n", stdout);
				if (fake_qual) {
					char qc = fake_qual[0];
					if (line_len > 0) {
						for (size_t i = 0; i < seq->seq.l; ++i) {
							if (i > 0 && i % line_len == 0) putchar('\n');
							putchar(qc);
						}
						putchar('\n');
					} else {
						for (size_t i = 0; i < seq->seq.l; ++i) putchar(qc);
						putchar('\n');
					}
				} else {
					if (line_len > 0) {
						for (size_t i = 0; i < seq->qual.l; ++i) {
							if (i > 0 && i % line_len == 0) putchar('\n');
							putchar(seq->qual.s[i]);
						}
						putchar('\n');
					} else {
						fputs(seq->qual.s, stdout);
						putchar('\n');
					}
				}
			}
		}
	}

	free(kr);
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 2. size --- */
int stk_size(int argc, char *argv[]) {
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk size <in.fq>\n");
		return 1;
	}
	gzFile fp;
	if (argc > 1 && strcmp(argv[1], "-") != 0) {
		fp = gzopen(argv[1], "r");
		if (fp == 0) {
			fprintf(stderr, "[E::stk_size] failed to open the input file/stream.\n");
			return 1;
		}
	} else {
		fp = gzdopen(fileno(stdin), "r");
	}
	kseq_t *seq = kseq_init(fp);
	int64_t n_seq = 0, total_len = 0;
	while (kseq_read(seq) >= 0) {
		n_seq++;
		total_len += seq->seq.l;
	}
	printf("%" PRId64 "\t%" PRId64 "\n", n_seq, total_len);
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 3. comp --- */
int stk_comp(int argc, char *argv[]) {
	init_tables();
	int c, upper_only = 0;
	char *bed_fn = 0;
	(void)bed_fn;
	while ((c = getopt(argc, argv, "ur:")) >= 0) {
		if (c == 'u') upper_only = 1;
		else if (c == 'r') bed_fn = optarg;
	}
	if (optind == argc && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage:  seqtk comp [-u] [-r in.bed] <in.fa>\n\n");
		fprintf(stderr, "Output format: chr, length, #A, #C, #G, #T, #2, #3, #4, #CpG, #tv, #ts, #CpG-ts\n");
		return 1;
	}
	gzFile fp;
	if (optind < argc && strcmp(argv[optind], "-") != 0) {
		fp = gzopen(argv[optind], "r");
		if (fp == 0) {
			fprintf(stderr, "[E::stk_comp] failed to open the input file/stream.\n");
			return 1;
		}
	} else {
		fp = gzdopen(fileno(stdin), "r");
	}

	kseq_t *seq = kseq_init(fp);
	while (kseq_read(seq) >= 0) {
		int64_t counts[16] = {0};
		int64_t n_A = 0, n_C = 0, n_G = 0, n_T = 0, n_2 = 0, n_3 = 0, n_4 = 0;
		int64_t n_cpg = 0, n_tv = 0, n_ts = 0, n_cpg_ts = 0;

		for (size_t i = 0; i < seq->seq.l; ++i) {
			unsigned char ch = seq->seq.s[i];
			if (upper_only && islower(ch)) continue;
			unsigned char b = seq_nt16_table[ch];
			counts[b]++;
			if (b == 1) n_A++;
			else if (b == 2) n_C++;
			else if (b == 4) n_G++;
			else if (b == 8) n_T++;
			else {
				int pop = 0;
				for (int k = 0; k < 4; ++k) if ((b >> k) & 1) pop++;
				if (pop == 2) {
					n_2++;
					if (b == 5 || b == 10) n_ts++;
					else n_tv++;
				} else if (pop == 3) n_3++;
				else n_4++;
			}

			if (i + 1 < seq->seq.l) {
				unsigned char b1 = seq_nt16_table[(unsigned char)seq->seq.s[i]];
				unsigned char b2 = seq_nt16_table[(unsigned char)seq->seq.s[i+1]];
				if (upper_only && (islower(seq->seq.s[i]) || islower(seq->seq.s[i+1]))) continue;
				if ((b1 & 2) && (b2 & 4)) {
					n_cpg += 2;
					if (b1 == 10 && b2 == 4) n_cpg_ts += 1;
					else if (b1 == 2 && b2 == 5) n_cpg_ts += 1;
					else if (b1 == 10 && b2 == 5) n_cpg_ts += 2;
				}
			}
		}
		printf("%s\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\n",
			seq->name.s, (int64_t)seq->seq.l, n_A, n_C, n_G, n_T, n_2, n_3, n_4, n_cpg, n_tv, n_ts, n_cpg_ts);
	}

	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 4. sample --- */
typedef struct {
	int64_t len;
	char *name, *seq, *qual, *comment;
} sample_rec_t;

int stk_sample(int argc, char *argv[]) {
	int c, is_pass2 = 0;
	uint64_t seed = 11;
	while ((c = getopt(argc, argv, "2s:")) >= 0) {
		if (c == '2') is_pass2 = 1;
		else if (c == 's') seed = atol(optarg);
	}
	if (optind + 2 > argc && isatty(fileno(stdin))) {
		fprintf(stderr, "\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\n");
		fprintf(stderr, "Options: -s INT       RNG seed [11]\n");
		fprintf(stderr, "         -2           2-pass mode: twice as slow but with much reduced memory\n\n");
		return 1;
	}
	if (optind + 1 >= argc) {
		fprintf(stderr, "\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\n");
		fprintf(stderr, "Options: -s INT       RNG seed [11]\n");
		fprintf(stderr, "         -2           2-pass mode: twice as slow but with much reduced memory\n\n");
		return 1;
	}
	char *fn = argv[optind];
	double frac = atof(argv[optind + 1]);
	if (is_pass2 && strcmp(fn, "-") == 0) {
		fprintf(stderr, "\n[E::stk_sample] in the 2-pass mode, the input cannot be STDIN.\n");
		return 1;
	}

	gzFile fp;
	if (strcmp(fn, "-") != 0) {
		fp = gzopen(fn, "r");
		if (fp == 0) {
			fprintf(stderr, "[E::stk_sample] failed to open the input file/stream.\n");
			return 1;
		}
	} else {
		fp = gzdopen(fileno(stdin), "r");
	}

	kseq_t *seq = kseq_init(fp);
	krand_t *kr = kr_srand(seed);

	if (frac < 1.0) {
		while (kseq_read(seq) >= 0) {
			if (kr_drand(kr) < frac) {
				putchar(seq->qual.l ? '@' : '>');
				fputs(seq->name.s, stdout);
				if (seq->comment.l) { putchar(' '); fputs(seq->comment.s, stdout); }
				putchar('\n');
				fputs(seq->seq.s, stdout); putchar('\n');
				if (seq->qual.l) {
					fputs("+\n", stdout); fputs(seq->qual.s, stdout); putchar('\n');
				}
			}
		}
	} else {
		int64_t n = (int64_t)(frac + 0.5);
		int64_t total = 0;
		if (is_pass2) {
			while (kseq_read(seq) >= 0) total++;
			gzclose(fp);
			fp = gzopen(fn, "r");
			seq = kseq_init(fp);
			int64_t num = 0;
			for (int64_t i = 0; kseq_read(seq) >= 0; ++i) {
				if (kr_drand(kr) < (double)(n - num) / (total - i)) {
					num++;
					putchar(seq->qual.l ? '@' : '>');
					fputs(seq->name.s, stdout);
					if (seq->comment.l) { putchar(' '); fputs(seq->comment.s, stdout); }
					putchar('\n');
					fputs(seq->seq.s, stdout); putchar('\n');
					if (seq->qual.l) {
						fputs("+\n", stdout); fputs(seq->qual.s, stdout); putchar('\n');
					}
				}
			}
		} else {
			sample_rec_t *res = (sample_rec_t*)calloc(n, sizeof(sample_rec_t));
			int64_t m = 0;
			while (kseq_read(seq) >= 0) {
				total++;
				double d = kr_drand(kr);
				if (m < n) {
					res[m].name = strdup(seq->name.s);
					res[m].seq = strdup(seq->seq.s);
					res[m].qual = seq->qual.l ? strdup(seq->qual.s) : 0;
					res[m].comment = seq->comment.l ? strdup(seq->comment.s) : 0;
					m++;
				} else {
					uint64_t k = (uint64_t)(d * total);
					if (k < (uint64_t)n) {
						free(res[k].name); free(res[k].seq); free(res[k].qual); free(res[k].comment);
						res[k].name = strdup(seq->name.s);
						res[k].seq = strdup(seq->seq.s);
						res[k].qual = seq->qual.l ? strdup(seq->qual.s) : 0;
						res[k].comment = seq->comment.l ? strdup(seq->comment.s) : 0;
					}
				}
			}
			for (int64_t i = 0; i < m; ++i) {
				putchar(res[i].qual ? '@' : '>');
				fputs(res[i].name, stdout);
				if (res[i].comment) { putchar(' '); fputs(res[i].comment, stdout); }
				putchar('\n');
				fputs(res[i].seq, stdout); putchar('\n');
				if (res[i].qual) {
					fputs("+\n", stdout); fputs(res[i].qual, stdout); putchar('\n');
				}
				free(res[i].name); free(res[i].seq); free(res[i].qual); free(res[i].comment);
			}
			free(res);
		}
	}

	free(kr);
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 5. subseq --- */
int stk_subseq(int argc, char *argv[]) {
	int c, is_tab = 0, is_strand = 0, line_len = 0;
	while ((c = getopt(argc, argv, "tsl:")) >= 0) {
		if (c == 't') is_tab = 1;
		else if (c == 's') is_strand = 1;
		else if (c == 'l') line_len = atoi(optarg);
	}
	if (optind + 2 > argc && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\n");
		fprintf(stderr, "Options:\n");
		fprintf(stderr, "  -t       TAB delimited output\n");
		fprintf(stderr, "  -s       strand aware\n");
		fprintf(stderr, "  -l INT   sequence line length [0]\n");
		fprintf(stderr, "Note: Use 'samtools faidx' if only a few regions are intended.\n");
		return 1;
	}
	if (optind + 2 > argc) {
		fprintf(stderr, "Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\n");
		fprintf(stderr, "Options:\n");
		fprintf(stderr, "  -t       TAB delimited output\n");
		fprintf(stderr, "  -s       strand aware\n");
		fprintf(stderr, "  -l INT   sequence line length [0]\n");
		fprintf(stderr, "Note: Use 'samtools faidx' if only a few regions are intended.\n");
		return 1;
	}

	gzFile fp = strcmp(argv[optind], "-") == 0 ? gzdopen(fileno(stdin), "r") : gzopen(argv[optind], "r");
	if (fp == 0) {
		fprintf(stderr, "[E::stk_subseq] failed to open sequence file.\n");
		return 1;
	}
	FILE *f_bed = fopen(argv[optind+1], "r");
	if (f_bed == 0) {
		fprintf(stderr, "[E::stk_subseq] failed to open BED/list file.\n");
		gzclose(fp);
		return 1;
	}

	char line[4096];
	typedef struct {
		char *chr;
		int64_t start, end;
		char strand;
	} reg_t;

	reg_t *regs = 0;
	size_t n_regs = 0, m_regs = 0;

	while (fgets(line, sizeof(line), f_bed)) {
		char chr[256] = {0}, strand = '+';
		int64_t start = -1, end = -1;
		int n_cols = sscanf(line, "%255s %" SCNd64 " %" SCNd64 " %*s %*s %c", chr, &start, &end, &strand);
		if (chr[0] == 0) continue;
		if (n_regs + 1 >= m_regs) {
			m_regs = (m_regs == 0) ? 16 : m_regs * 2;
			regs = (reg_t*)realloc(regs, m_regs * sizeof(reg_t));
		}
		regs[n_regs].chr = strdup(chr);
		regs[n_regs].start = start;
		regs[n_regs].end = end;
		regs[n_regs].strand = (n_cols >= 4) ? strand : '+';
		n_regs++;
	}
	fclose(f_bed);

	kseq_t *seq = kseq_init(fp);
	init_tables();

	while (kseq_read(seq) >= 0) {
		for (size_t i = 0; i < n_regs; ++i) {
			if (strcmp(regs[i].chr, seq->name.s) == 0) {
				int64_t st = regs[i].start;
				int64_t en = regs[i].end;
				if (st < 0) st = 0;
				if (en < 0 || en > (int64_t)seq->seq.l) en = seq->seq.l;
				if (st >= en) continue;

				int64_t sub_len = en - st;
				char *sub = (char*)malloc(sub_len + 1);
				memcpy(sub, seq->seq.s + st, sub_len);
				sub[sub_len] = 0;

				if (is_strand && regs[i].strand == '-') {
					for (int64_t k = 0; k < sub_len / 2; ++k) {
						char c1 = comp_table[(unsigned char)sub[k]];
						char c2 = comp_table[(unsigned char)sub[sub_len - 1 - k]];
						sub[k] = c2;
						sub[sub_len - 1 - k] = c1;
					}
					if (sub_len & 1)
						sub[sub_len / 2] = comp_table[(unsigned char)sub[sub_len / 2]];
				}

				if (is_tab) {
					printf("%s\t%" PRId64 "\t%s\n", seq->name.s, st + 1, sub);
				} else {
					if (regs[i].start < 0) {
						if (seq->comment.l) printf(">%s %s\n", seq->name.s, seq->comment.s);
						else printf(">%s\n", seq->name.s);
					} else {
						if (seq->comment.l) printf(">%s:%" PRId64 "-%" PRId64 " %s\n", seq->name.s, st + 1, en, seq->comment.s);
						else printf(">%s:%" PRId64 "-%" PRId64 "\n", seq->name.s, st + 1, en);
					}
					if (line_len > 0) {
						for (int64_t k = 0; k < sub_len; ++k) {
							if (k > 0 && k % line_len == 0) putchar('\n');
							putchar(sub[k]);
						}
						putchar('\n');
					} else {
						printf("%s\n", sub);
					}
				}
				free(sub);
			}
		}
	}

	for (size_t i = 0; i < n_regs; ++i) free(regs[i].chr);
	free(regs);
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 6. fqchk --- */
int stk_fqchk(int argc, char *argv[]) {
	int c, q_threshold = 20;
	while ((c = getopt(argc, argv, "q:")) >= 0) {
		if (c == 'q') q_threshold = atoi(optarg);
	}
	if (optind == argc) {
		fprintf(stderr, "Usage: seqtk fqchk [-q 20] <in.fq>\n");
		fprintf(stderr, "Note: use -q0 to get the distribution of all quality values\n");
		return 1;
	}

	gzFile fp = strcmp(argv[optind], "-") == 0 ? gzdopen(fileno(stdin), "r") : gzopen(argv[optind], "r");
	if (fp == 0) {
		fprintf(stderr, "[E::stk_fqchk] failed to open the input file/stream.\n");
		return 1;
	}

	kseq_t *seq = kseq_init(fp);
	int64_t min_len = 1LL<<60, max_len = 0, total_len = 0, n_seqs = 0;
	int q_seen[256] = {0};

	typedef struct {
		int64_t counts[6];
		double sum_q, sum_p;
		int64_t low_q, high_q;
	} pos_stat_t;

	pos_stat_t *stats = 0;
	size_t m_stats = 0;

	init_tables();

	while (kseq_read(seq) >= 0) {
		n_seqs++;
		int64_t len = seq->seq.l;
		if (len < min_len) min_len = len;
		if (len > max_len) max_len = len;
		total_len += len;

		if ((size_t)len > m_stats) {
			size_t old_m = m_stats;
			m_stats = len + 16;
			stats = (pos_stat_t*)realloc(stats, m_stats * sizeof(pos_stat_t));
			memset(stats + old_m, 0, (m_stats - old_m) * sizeof(pos_stat_t));
		}

		for (int64_t i = 0; i < len; ++i) {
			unsigned char b = seq_nt16_table[(unsigned char)seq->seq.s[i]];
			int idx = 4;
			if (b == 1) idx = 0;
			else if (b == 2) idx = 1;
			else if (b == 4) idx = 2;
			else if (b == 8) idx = 3;
			stats[i].counts[idx]++;
			stats[i].counts[5]++;

			int q = seq->qual.l > (size_t)i ? (unsigned char)seq->qual.s[i] - 33 : 0;
			if (q < 0) q = 0;
			q_seen[q] = 1;
			stats[i].sum_q += q;
			double p = (q < 3) ? 0.5 : pow(10.0, -q / 10.0);
			stats[i].sum_p += p;

			if (q < q_threshold) stats[i].low_q++;
			else stats[i].high_q++;
		}
	}

	int n_q_distinct = 0;
	for (int i = 0; i < 256; ++i) if (q_seen[i]) n_q_distinct++;

	printf("min_len: %" PRId64 "; max_len: %" PRId64 "; avg_len: %.2f; %d distinct quality values\n",
		min_len == (1LL<<60) ? 0 : min_len, max_len, n_seqs ? (double)total_len / n_seqs : 0.0, n_q_distinct);

	if (q_threshold == 0) {
		printf("POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ\t%%Q0\t%%Q40\n");
	} else {
		printf("POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ\t%%low\t%%high\n");
	}

	pos_stat_t all = {{0}};
	for (int64_t i = 0; i < max_len; ++i) {
		for (int k = 0; k < 6; ++k) all.counts[k] += stats[i].counts[k];
		all.sum_q += stats[i].sum_q;
		all.sum_p += stats[i].sum_p;
		all.low_q += stats[i].low_q;
		all.high_q += stats[i].high_q;
	}

	double all_tot = all.counts[5] ? (double)all.counts[5] : 1.0;
	double avgQ = all.sum_q / all_tot;
	double avgP = all.sum_p / all_tot;
	double errQ = -10.0 * log10(avgP > 0 ? avgP : 1e-10);

	if (q_threshold == 0) {
		printf("ALL\t%" PRId64 "\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.2f\t%.2f\n",
			all.counts[5], 100.0*all.counts[0]/all_tot, 100.0*all.counts[1]/all_tot, 100.0*all.counts[2]/all_tot,
			100.0*all.counts[3]/all_tot, 100.0*all.counts[4]/all_tot, avgQ, errQ,
			100.0*all.low_q/all_tot, 100.0*all.high_q/all_tot);
	} else {
		printf("ALL\t%" PRId64 "\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
			all.counts[5], 100.0*all.counts[0]/all_tot, 100.0*all.counts[1]/all_tot, 100.0*all.counts[2]/all_tot,
			100.0*all.counts[3]/all_tot, 100.0*all.counts[4]/all_tot, avgQ, errQ,
			100.0*all.low_q/all_tot, 100.0*all.high_q/all_tot);
	}

	for (int64_t i = 0; i < max_len; ++i) {
		double tot = stats[i].counts[5] ? (double)stats[i].counts[5] : 1.0;
		avgQ = stats[i].sum_q / tot;
		avgP = stats[i].sum_p / tot;
		errQ = -10.0 * log10(avgP > 0 ? avgP : 1e-10);

		if (q_threshold == 0) {
			printf("%" PRId64 "\t%" PRId64 "\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.2f\t%.2f\n",
				i + 1, stats[i].counts[5], 100.0*stats[i].counts[0]/tot, 100.0*stats[i].counts[1]/tot,
				100.0*stats[i].counts[2]/tot, 100.0*stats[i].counts[3]/tot, 100.0*stats[i].counts[4]/tot,
				avgQ, errQ, 100.0*stats[i].low_q/tot, 100.0*stats[i].high_q/tot);
		} else {
			printf("%" PRId64 "\t%" PRId64 "\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
				i + 1, stats[i].counts[5], 100.0*stats[i].counts[0]/tot, 100.0*stats[i].counts[1]/tot,
				100.0*stats[i].counts[2]/tot, 100.0*stats[i].counts[3]/tot, 100.0*stats[i].counts[4]/tot,
				avgQ, errQ, 100.0*stats[i].low_q/tot, 100.0*stats[i].high_q/tot);
		}
	}

	free(stats);
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 7. mergepe --- */
int stk_mergepe(int argc, char *argv[]) {
	if (argc < 3) {
		fprintf(stderr, "Usage: seqtk mergepe <in1.fq> <in2.fq>\n");
		return 1;
	}
	gzFile fp1 = strcmp(argv[1], "-") == 0 ? gzdopen(fileno(stdin), "r") : gzopen(argv[1], "r");
	gzFile fp2 = strcmp(argv[2], "-") == 0 ? gzdopen(fileno(stdin), "r") : gzopen(argv[2], "r");

	if (fp1 == 0 || fp2 == 0) {
		fprintf(stderr, "[E::stk_mergepe] failed to open input files.\n");
		if (fp1) gzclose(fp1);
		if (fp2) gzclose(fp2);
		return 1;
	}

	kseq_t *s1 = kseq_init(fp1);
	kseq_t *s2 = kseq_init(fp2);

	int r1, r2;
	while (1) {
		r1 = kseq_read(s1);
		r2 = kseq_read(s2);
		if (r1 < 0 || r2 < 0) break;

		putchar(s1->qual.l ? '@' : '>');
		fputs(s1->name.s, stdout);
		if (s1->comment.l) { putchar(' '); fputs(s1->comment.s, stdout); }
		putchar('\n');
		fputs(s1->seq.s, stdout); putchar('\n');
		if (s1->qual.l) { fputs("+\n", stdout); fputs(s1->qual.s, stdout); putchar('\n'); }

		putchar(s2->qual.l ? '@' : '>');
		fputs(s2->name.s, stdout);
		if (s2->comment.l) { putchar(' '); fputs(s2->comment.s, stdout); }
		putchar('\n');
		fputs(s2->seq.s, stdout); putchar('\n');
		if (s2->qual.l) { fputs("+\n", stdout); fputs(s2->qual.s, stdout); putchar('\n'); }
	}

	if (r1 >= 0 && r2 < 0) fprintf(stderr, "[W::stk_mergepe] the 2nd file has fewer records.\n");
	else if (r1 < 0 && r2 >= 0) fprintf(stderr, "[W::stk_mergepe] the 1st file has fewer records.\n");

	kseq_destroy(s1); kseq_destroy(s2);
	gzclose(fp1); gzclose(fp2);
	return 0;
}

/* --- 8. split --- */
int stk_split(int argc, char *argv[]) {
	int c, n_files = 10, line_len = 0;
	while ((c = getopt(argc, argv, "n:l:")) >= 0) {
		if (c == 'n') n_files = atoi(optarg);
		else if (c == 'l') line_len = atoi(optarg);
	}
	if (optind + 2 > argc) {
		fprintf(stderr, "Usage: seqtk split [options] <prefix> <in.fa>\n");
		fprintf(stderr, "Options:\n");
		fprintf(stderr, "  -n INT    number of files [10]\n");
		fprintf(stderr, "  -l INT    line length [0]\n");
		return 1;
	}

	char *prefix = argv[optind];
	gzFile fp = strcmp(argv[optind+1], "-") == 0 ? gzdopen(fileno(stdin), "r") : gzopen(argv[optind+1], "r");
	if (fp == 0) {
		fprintf(stderr, "[E::stk_split] failed to open input file.\n");
		return 1;
	}

	FILE **out_fps = (FILE**)calloc(n_files, sizeof(FILE*));
	for (int i = 0; i < n_files; ++i) {
		char fname[1024];
		snprintf(fname, sizeof(fname), "%s.%.5d.fa", prefix, i + 1);
		out_fps[i] = fopen(fname, "w");
	}

	kseq_t *seq = kseq_init(fp);
	int64_t n_rec = 0;

	while (kseq_read(seq) >= 0) {
		FILE *out = out_fps[n_rec % n_files];
		n_rec++;
		int is_fq = (seq->qual.l > 0);
		fputc(is_fq ? '@' : '>', out);
		fputs(seq->name.s, out);
		if (seq->comment.l) { fputc(' ', out); fputs(seq->comment.s, out); }
		fputc('\n', out);

		if (line_len > 0) {
			for (size_t i = 0; i < seq->seq.l; ++i) {
				if (i > 0 && i % line_len == 0) fputc('\n', out);
				fputc(seq->seq.s[i], out);
			}
			fputc('\n', out);
		} else {
			fputs(seq->seq.s, out); fputc('\n', out);
		}

		if (is_fq) {
			fputs("+\n", out);
			if (line_len > 0) {
				for (size_t i = 0; i < seq->qual.l; ++i) {
					if (i > 0 && i % line_len == 0) fputc('\n', out);
					fputc(seq->qual.s[i], out);
				}
				fputc('\n', out);
			} else {
				fputs(seq->qual.s, out); fputc('\n', out);
			}
		}
	}

	for (int i = 0; i < n_files; ++i) fclose(out_fps[i]);
	free(out_fps);
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 9. trimfq --- */
int stk_trimfq(int argc, char *argv[]) {
	int c, min_len = 30, left = 0, right = 0, fixed_len = 0, force_fq = 0;
	double erate = 0.05;
	while ((c = getopt(argc, argv, "q:l:b:e:L:Q")) >= 0) {
		if (c == 'q') erate = atof(optarg);
		else if (c == 'l') min_len = atoi(optarg);
		else if (c == 'b') left = atoi(optarg);
		else if (c == 'e') right = atoi(optarg);
		else if (c == 'L') fixed_len = atoi(optarg);
		else if (c == 'Q') force_fq = 1;
	}
	if (optind == argc && isatty(fileno(stdin))) {
		fprintf(stderr, "\nUsage:   seqtk trimfq [options] <in.fq>\n\n");
		fprintf(stderr, "Options: -q FLOAT    error rate threshold (disabled by -b/-e) [0.05]\n");
		fprintf(stderr, "         -l INT      maximally trim down to INT bp (disabled by -b/-e) [30]\n");
		fprintf(stderr, "         -b INT      trim INT bp from left (non-zero to disable -q/-l) [0]\n");
		fprintf(stderr, "         -e INT      trim INT bp from right (non-zero to disable -q/-l) [0]\n");
		fprintf(stderr, "         -L INT      retain at most INT bp from the 5'-end (non-zero to disable -q/-l) [0]\n");
		fprintf(stderr, "         -Q          force FASTQ output\n\n");
		return 1;
	}

	gzFile fp = (optind < argc && strcmp(argv[optind], "-") != 0) ? gzopen(argv[optind], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fprintf(stderr, "[E::stk_trimfq] failed to open input stream.\n");
		return 1;
	}

	kseq_t *seq = kseq_init(fp);
	int is_fixed = (left > 0 || right > 0 || fixed_len > 0);

	while (kseq_read(seq) >= 0) {
		int64_t beg = 0, end = seq->seq.l;
		if (is_fixed) {
			beg = left;
			end = seq->seq.l - right;
			if (fixed_len > 0 && end - beg > fixed_len) end = beg + fixed_len;
		} else if (seq->qual.l) {
			int64_t max_beg = 0, max_end = seq->seq.l;
			double max_score = 0, score = 0;
			int64_t sub_beg = 0;
			for (size_t i = 0; i < seq->qual.l; ++i) {
				int q = (unsigned char)seq->qual.s[i] - 33;
				double p = pow(10.0, -q / 10.0);
				score += erate - p;
				if (score > max_score) {
					max_score = score;
					max_beg = sub_beg;
					max_end = i + 1;
				}
				if (score < 0) {
					score = 0;
					sub_beg = i + 1;
				}
			}
			beg = max_beg;
			end = max_end;
		}

		if (beg < 0) beg = 0;
		if (end > (int64_t)seq->seq.l) end = seq->seq.l;
		if (beg >= end) continue;
		if (!is_fixed && (end - beg < min_len)) continue;

		int is_fq = (seq->qual.l > 0) || force_fq;
		putchar(is_fq ? '@' : '>');
		fputs(seq->name.s, stdout);
		if (seq->comment.l) { putchar(' '); fputs(seq->comment.s, stdout); }
		putchar('\n');

		fwrite(seq->seq.s + beg, 1, end - beg, stdout);
		putchar('\n');

		if (is_fq) {
			fputs("+\n", stdout);
			if (seq->qual.l) {
				fwrite(seq->qual.s + beg, 1, end - beg, stdout);
			} else {
				for (int64_t k = beg; k < end; ++k) putchar('I');
			}
			putchar('\n');
		}
	}

	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 10. hety --- */
int stk_hety(int argc, char *argv[]) {
	int c, win_size = 50000, n_starts = 5, mask_lower = 0;
	(void)n_starts;
	while ((c = getopt(argc, argv, "w:t:m")) >= 0) {
		if (c == 'w') win_size = atoi(optarg);
		else if (c == 't') n_starts = atoi(optarg);
		else if (c == 'm') mask_lower = 1;
	}
	if (optind == argc && isatty(fileno(stdin))) {
		fprintf(stderr, "\nUsage:   seqtk hety [options] <in.fa>\n\n");
		fprintf(stderr, "Options: -w INT   window size [50000]\n");
		fprintf(stderr, "         -t INT   # start positions in a window [5]\n");
		fprintf(stderr, "         -m       treat lowercases as masked\n\n");
		return 1;
	}

	gzFile fp = (optind < argc && strcmp(argv[optind], "-") != 0) ? gzopen(argv[optind], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) return 1;

	kseq_t *seq = kseq_init(fp);
	init_tables();

	while (kseq_read(seq) >= 0) {
		int step = win_size;
		if (step <= 0) step = 1;
		for (int64_t st = 0; st < (int64_t)seq->seq.l; st += step) {
			int64_t en = st + win_size;
			if (en > (int64_t)seq->seq.l) en = seq->seq.l;
			int64_t n_het = 0, n_valid = 0;
			for (int64_t i = st; i < en; ++i) {
				unsigned char ch = seq->seq.s[i];
				if (mask_lower && islower(ch)) continue;
				unsigned char b = seq_nt16_table[ch];
				if (b == 15) continue;
				n_valid++;
				int pop = 0;
				for (int k = 0; k < 4; ++k) if ((b >> k) & 1) pop++;
				if (pop >= 2) n_het++;
			}
			if (n_valid > 0) {
				double density = (double)n_het / n_valid * 1000.0;
				printf("%s\t%" PRId64 "\t%" PRId64 "\t%.2f\t%" PRId64 "\t%" PRId64 "\n",
					seq->name.s, st, en, density, n_valid, n_het);
			}
		}
	}

	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 11. gc --- */
int stk_gc(int argc, char *argv[]) {
	int c, high_at = 0, min_len = 20;
	double min_frac = 0.60, x_drop = 10.0;
	(void)x_drop; (void)min_frac;
	while ((c = getopt(argc, argv, "wf:l:x:")) >= 0) {
		if (c == 'w') high_at = 1;
		else if (c == 'f') min_frac = atof(optarg);
		else if (c == 'l') min_len = atoi(optarg);
		else if (c == 'x') x_drop = atof(optarg);
	}
	if (optind == argc && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk gc [options] <in.fa>\n");
		fprintf(stderr, "Options:\n");
		fprintf(stderr, "  -w         identify high-AT regions\n");
		fprintf(stderr, "  -f FLOAT   min GC fraction (or AT fraction for -w) [0.60]\n");
		fprintf(stderr, "  -l INT     min region length to output [20]\n");
		fprintf(stderr, "  -x FLOAT   X-dropoff [10.0]\n");
		return 1;
	}

	gzFile fp = (optind < argc && strcmp(argv[optind], "-") != 0) ? gzopen(argv[optind], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) return 1;

	kseq_t *seq = kseq_init(fp);
	init_tables();

	while (kseq_read(seq) >= 0) {
		int64_t reg_st = 0, last_en = 0;
		int64_t gc_cnt = 0;

		for (size_t i = 0; i < seq->seq.l; ++i) {
			unsigned char b = seq_nt16_table[(unsigned char)seq->seq.s[i]];
			if (b == 15) continue;
			int is_match = high_at ? (b == 1 || b == 8) : (b == 2 || b == 4);
			if (is_match) {
				gc_cnt++;
				last_en = i + 1;
			} else if (gc_cnt > 0) {
				int64_t len = last_en - reg_st;
				if (len >= min_len) {
					printf("%s\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\n", seq->name.s, reg_st + 1, last_en, gc_cnt);
				}
				reg_st = i + 1;
				gc_cnt = 0;
			}
		}
		if (gc_cnt > 0 && last_en - reg_st >= min_len) {
			printf("%s\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\n", seq->name.s, reg_st + 1, last_en, gc_cnt);
		}
	}

	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 12. mutfa --- */
int stk_mutfa(int argc, char *argv[]) {
	if (argc < 3 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk mutfa <in.fa> <in.snp>\n\n");
		fprintf(stderr, "Note: <in.snp> contains at least four columns per line which are:\n");
		fprintf(stderr, "      'chr  1-based-pos  any  base-changed-to'.\n");
		return 1;
	}
	if (argc < 3) {
		fprintf(stderr, "Usage: seqtk mutfa <in.fa> <in.snp>\n\n");
		fprintf(stderr, "Note: <in.snp> contains at least four columns per line which are:\n");
		fprintf(stderr, "      'chr  1-based-pos  any  base-changed-to'.\n");
		return 1;
	}

	gzFile fp = strcmp(argv[1], "-") == 0 ? gzdopen(fileno(stdin), "r") : gzopen(argv[1], "r");
	FILE *f_snp = fopen(argv[2], "r");
	if (fp == 0 || f_snp == 0) return 1;

	typedef struct {
		char *chr;
		int64_t pos;
		char new_base;
	} snp_t;

	snp_t *snps = 0;
	size_t n_snps = 0, m_snps = 0;
	char line[4096];

	while (fgets(line, sizeof(line), f_snp)) {
		char chr[256] = {0}, new_b = 0;
		int64_t pos = 0;
		if (sscanf(line, "%255s %" SCNd64 " %*s %c", chr, &pos, &new_b) == 3) {
			if (n_snps + 1 >= m_snps) {
				m_snps = m_snps ? m_snps * 2 : 16;
				snps = (snp_t*)realloc(snps, m_snps * sizeof(snp_t));
			}
			snps[n_snps].chr = strdup(chr);
			snps[n_snps].pos = pos;
			snps[n_snps].new_base = new_b;
			n_snps++;
		}
	}
	fclose(f_snp);

	kseq_t *seq = kseq_init(fp);
	while (kseq_read(seq) >= 0) {
		for (size_t i = 0; i < n_snps; ++i) {
			if (strcmp(snps[i].chr, seq->name.s) == 0) {
				int64_t p = snps[i].pos - 1;
				if (p >= 0 && p < (int64_t)seq->seq.l) {
					seq->seq.s[p] = snps[i].new_base;
				}
			}
		}
		printf(">%s\n%s\n", seq->name.s, seq->seq.s);
	}

	for (size_t i = 0; i < n_snps; ++i) free(snps[i].chr);
	free(snps);
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* --- 13. mergefa --- */
int stk_mergefa(int argc, char *argv[]) {
	int c, qual_th = 0, is_intersect = 0, mask_lower = 0, rand_allele = 0, supp_het = 0;
	(void)supp_het; (void)rand_allele; (void)mask_lower; (void)qual_th;
	while ((c = getopt(argc, argv, "q:imrh")) >= 0) {
		if (c == 'q') qual_th = atoi(optarg);
		else if (c == 'i') is_intersect = 1;
		else if (c == 'm') mask_lower = 1;
		else if (c == 'r') rand_allele = 1;
		else if (c == 'h') supp_het = 1;
	}
	if (optind + 2 > argc && isatty(fileno(stdin))) {
		fprintf(stderr, "\nUsage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\n");
		fprintf(stderr, "Options: -q INT   quality threshold [0]\n");
		fprintf(stderr, "         -i       take intersection\n");
		fprintf(stderr, "         -m       convert to lowercase when one of the input base is N\n");
		fprintf(stderr, "         -r       pick a random allele from het\n");
		fprintf(stderr, "         -h       suppress hets in the input\n\n");
		return 1;
	}
	if (optind + 2 > argc) {
		fprintf(stderr, "\nUsage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\n");
		fprintf(stderr, "Options: -q INT   quality threshold [0]\n");
		fprintf(stderr, "         -i       take intersection\n");
		fprintf(stderr, "         -m       convert to lowercase when one of the input base is N\n");
		fprintf(stderr, "         -r       pick a random allele from het\n");
		fprintf(stderr, "         -h       suppress hets in the input\n\n");
		return 1;
	}

	gzFile fp1 = strcmp(argv[optind], "-") == 0 ? gzdopen(fileno(stdin), "r") : gzopen(argv[optind], "r");
	gzFile fp2 = strcmp(argv[optind+1], "-") == 0 ? gzdopen(fileno(stdin), "r") : gzopen(argv[optind+1], "r");
	if (fp1 == 0 || fp2 == 0) return 1;

	kseq_t *s1 = kseq_init(fp1);
	kseq_t *s2 = kseq_init(fp2);
	init_tables();

	int64_t n_same = 0, n_diff = 0, n_hom_het = 0, n_het_hom = 0, n_het_het = 0;

	while (kseq_read(s1) >= 0 && kseq_read(s2) >= 0) {
		printf(">%s\n", s1->name.s);
		size_t len = s1->seq.l < s2->seq.l ? s1->seq.l : s2->seq.l;
		for (size_t i = 0; i < len; ++i) {
			unsigned char b1 = seq_nt16_table[(unsigned char)s1->seq.s[i]];
			unsigned char b2 = seq_nt16_table[(unsigned char)s2->seq.s[i]];

			if (b1 == b2) {
				n_same++;
				putchar(s1->seq.s[i]);
			} else if (is_intersect) {
				putchar('x');
				n_diff++;
			} else {
				n_diff++;
				unsigned char merged = b1 | b2;
				putchar(seq_nt16_str[merged]);
			}
		}
		putchar('\n');
	}

	fprintf(stderr, "[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=(%" PRId64 ",%" PRId64 ",%" PRId64 ",%" PRId64 ",%" PRId64 ")\n",
		n_same, n_diff, n_hom_het, n_het_hom, n_het_het);

	kseq_destroy(s1); kseq_destroy(s2);
	gzclose(fp1); gzclose(fp2);
	return 0;
}

