		int64_t counts[16] = {0};
		int64_t n_A = 0, n_C = 0, n_G = 0, n_T = 0, n_2 = 0, n_3 = 0, n_4 = 0;
		int64_t n_cpg = 0, n_tv = 0, n_ts = 0, n_cpg_ts = 0;

