		return 1;
	}

	kseq_t *seq = kseq_init(fp);
	init_tables();

	while (kseq_read(seq) >= 0) {
		for (size_t i = 0; i < seq->seq.l; ++i) {
			unsigned char b = seq_nt16_table[(unsigned char)seq->seq.s[i]];
			if (b != 15) {
				int pop = 0;
				for (int k = 0; k < 4; ++k) if ((b >> k) & 1) pop++;
				if (pop >= 2) {
					printf("%s\t%" PRId64 "\t%c\n", seq->name.s, (int64_t)i + 1, seq->seq.s[i]);
				}
			}
