/* ==================== SUBCOMMAND IMPLEMENTATIONS ==================== */

/* --- 1. seq --- */
int stk_seq(int argc, char *argv[]) {
	init_tables();
	int c, q_min = 0, q_max = 255, line_len = 0, qual_shift = 33, drop_comments = 0;
	int is_rev = 0, is_both = 0, force_fa = 0, mask_chr = 0, drop_ambig = 0;
	int read_odd = 0, read_even = 0, shift_v = 0, to_upper = 0, lower_to_n = 0;
	int strip_space = 0, mask_comp = 0;
	int min_len = 0;
	double frac = 1.0;
	uint64_t seed = 11;
	char *fake_qual = 0, *mask_fn = 0;
	(void)mask_fn; (void)mask_comp; (void)q_max; (void)q_min;

	while ((c = getopt(argc, argv, "q:X:n:l:Q:s:f:M:L:F:crRA12VUxSNC")) >= 0) {
		if (c == 'q') q_min = atoi(optarg);
		else if (c == 'X') q_max = atoi(optarg);
		else if (c == 'n') mask_chr = optarg[0] == '0' ? 0 : optarg[0];
		else if (c == 'l') line_len = atoi(optarg);
		else if (c == 'Q') qual_shift = atoi(optarg);
		else if (c == 's') seed = atol(optarg);
		else if (c == 'f') frac = atof(optarg);
		else if (c == 'M') mask_fn = optarg;
