/* kstring_t */
#ifndef KSTRING_T
#define KSTRING_T kstring_t
typedef struct __kstring_t {
	size_t l, m;
	char *s;
} kstring_t;
#endif

/* kstream_t & kseq_t */
#define KS_BUF_SIZE 16384

typedef struct __kstream_t {
	unsigned char *buf;
	int begin, end, is_eof;
	gzFile f;
} kstream_t;

static inline kstream_t *ks_init(gzFile f) {
	kstream_t *ks = (kstream_t*)calloc(1, sizeof(kstream_t));
	ks->buf = (unsigned char*)malloc(KS_BUF_SIZE);
	ks->f = f;
	return ks;
}

static inline void ks_destroy(kstream_t *ks) {
	if (ks) {
		free(ks->buf);
		free(ks);
	}
}

static inline int ks_getc(kstream_t *ks) {
	if (ks->is_eof) return -1;
	if (ks->begin >= ks->end) {
		ks->begin = 0;
		ks->end = gzread(ks->f, ks->buf, KS_BUF_SIZE);
		if (ks->end <= 0) {
			ks->is_eof = 1;
			return -1;
		}
	}
	return ks->buf[ks->begin++];
}

static int ks_getuntil(kstream_t *ks, int delimiter, kstring_t *str, int *dret) {
	if (dret) *dret = 0;
	str->l = 0;
	if (ks->begin >= ks->end && ks->is_eof) return -1;
	for (;;) {
		int i;
		if (ks->begin >= ks->end) {
			if (!ks->is_eof) {
				ks->begin = 0;
				ks->end = gzread(ks->f, ks->buf, KS_BUF_SIZE);
				if (ks->end <= 0) {
					ks->is_eof = 1;
					break;
				}
			} else break;
		}
		if (delimiter == 0) { // whitespace
			for (i = ks->begin; i < ks->end; ++i)
				if (isspace(ks->buf[i])) break;
		} else if (delimiter == 1) { // newline
			for (i = ks->begin; i < ks->end; ++i)
				if (ks->buf[i] == '\n') break;
		} else if (delimiter == 2) { // \n or \r
			for (i = ks->begin; i < ks->end; ++i)
				if (ks->buf[i] == '\n' || ks->buf[i] == '\r') break;
		} else {
			for (i = ks->begin; i < ks->end; ++i)
				if (ks->buf[i] == delimiter) break;
		}
		if (i > ks->begin) {
			if (str->l + (i - ks->begin) + 1 >= str->m) {
				str->m = str->l + (i - ks->begin) + 1;
				str->m += (str->m >> 2) + 16;
				str->s = (char*)realloc(str->s, str->m);
			}
			memcpy(str->s + str->l, ks->buf + ks->begin, i - ks->begin);
			str->l += i - ks->begin;
			str->s[str->l] = 0;
		}
		ks->begin = i;
		if (i < ks->end) {
			if (dret) *dret = ks->buf[ks->begin++];
			else ++ks->begin;
			break;
		}
	}
	if (str->l == 0 && ks->is_eof) return -1;
	return str->l;
}

typedef struct {
	kstring_t name, comment, seq, qual;
	int last_char;
	kstream_t *f;
} kseq_t;

static inline kseq_t *kseq_init(gzFile f) {
	kseq_t *s = (kseq_t*)calloc(1, sizeof(kseq_t));
	s->f = ks_init(f);
	return s;
}

static inline void kseq_destroy(kseq_t *s) {
	if (!s) return;
	free(s->name.s); free(s->comment.s); free(s->seq.s); free(s->qual.s);
	ks_destroy(s->f);
	free(s);
}

static int kseq_read(kseq_t *seq) {
	int c;
	kstream_t *ks = seq->f;
	if (seq->last_char == 0) {
		while ((c = ks_getc(ks)) >= 0 && c != '>' && c != '@');
		if (c < 0) return -1;
		seq->last_char = c;
	}
	seq->name.l = seq->comment.l = seq->seq.l = seq->qual.l = 0;
	int dret = 0;
	c = ks_getuntil(ks, 0, &seq->name, &dret);
	if (c < 0) return -1;
	if (dret != '\n' && dret != '\r') {
		ks_getuntil(ks, 2, &seq->comment, 0);
	}
	while ((c = ks_getc(ks)) >= 0 && c != '>' && c != '@' && c != '+') {
		if (c == '\n' || c == '\r') continue;
		if (seq->seq.l + 1 >= seq->seq.m) {
			seq->seq.m = seq->seq.l + 2;
			seq->seq.m += (seq->seq.m >> 2) + 16;
			seq->seq.s = (char*)realloc(seq->seq.s, seq->seq.m);
		}
		seq->seq.s[seq->seq.l++] = c;
	}
	if (seq->seq.s) seq->seq.s[seq->seq.l] = 0;
	if (c == '>' || c == '@') seq->last_char = c;

	if (c == '+') {
		seq->last_char = 0;
		while ((c = ks_getc(ks)) >= 0 && c != '\n' && c != '\r');
		while ((c = ks_getc(ks)) >= 0) {
			if (c == '\n' || c == '\r') continue;
			if (seq->qual.l + 1 >= seq->qual.m) {
				seq->qual.m = seq->qual.l + 2;
				seq->qual.m += (seq->qual.m >> 2) + 16;
				seq->qual.s = (char*)realloc(seq->qual.s, seq->qual.m);
			}
			seq->qual.s[seq->qual.l++] = c;
			if (seq->qual.l >= seq->seq.l) break;
		}
		if (seq->qual.s) seq->qual.s[seq->qual.l] = 0;
	}
	return seq->seq.l;
}

/* krand_t implementation */
static inline uint64_t kr_splitmix64(uint64_t *x) {
	uint64_t z = (*x += 0x9E3779B97F4A7C15ULL);
	z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
	z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
	return z ^ (z >> 31);
}

typedef struct {
	uint64_t x[2];
} krand_t;

static inline uint64_t kr_rand(krand_t *r) {
	uint64_t x = r->x[0];
	uint64_t const y = r->x[1];
	r->x[0] = y;
	x ^= x << 23;
	r->x[1] = x ^ y ^ (x >> 17) ^ (y >> 26);
	return r->x[1] + y;
}

static inline double kr_drand(krand_t *r) {
	return (kr_rand(r) >> 11) * (1.0 / (1ULL << 53));
}

static inline krand_t *kr_srand(uint64_t seed) {
	krand_t *r = (krand_t*)calloc(1, sizeof(krand_t));
	r->x[0] = kr_splitmix64(&seed);
	r->x[1] = kr_splitmix64(&seed);
	kr_rand(r);
	return r;
}

